/**
 * Pre-Hydration Browser Zoom Detection
 *
 * This module runs BEFORE React hydration to detect and handle browser zoom.
 * to freeze font sizes if zoom is detected.
 *
 * Loading conditions (checked at template level in detect-browser-zoom.ejs):
 * - Studio (responsive sites) OR Editor 3 (builder component)
 * - Experiment enabled: specs.thunderbolt.browserZoomHandler
 *
 * Note: This file is compiled as an inline script bundle by webpack.
 * Imports are allowed and will be bundled together.
 */

import {
	freezeFonts,
	shouldApplyBrowserZoomHandling,
	detectCurrentZoomFactor,
	ensureAndroidBaseline,
} from './zoomUtils'
import { isExperimentOpen } from '@wix/thunderbolt-experiments'

// Pre-bootstrap: envApi is not available before hydration.
// window.viewerModel is the only source of experiments data at this stage.
const isMobileOnloadDetectionEnabled = (): boolean => {
	const experiments = (window as any).viewerModel?.experiments || {}
	return isExperimentOpen(experiments, 'specs.thunderbolt.browserZoomMobileOnloadDetection')
}

/**
 * Initialize browser zoom detection - runs before hydration.
 * Routing per device type lives in detectCurrentZoomFactor (zoomUtils),
 * so the pre-hydration and post-hydration paths share the same logic.
 *
 * Pre-hydration-only concern handled here: on Android, ensure the baseline
 * DPR is written on first ever visit so future loads can detect zoom by
 * comparison. The baseline is permanent once written — never updated.
 *
 * The browserZoomMobileOnloadDetection experiment gates the entire Android
 * baseline mechanism — both writing the baseline AND reading it. If we cancel
 * the experiment, Android short-circuits to "no on-load detection" instead of
 * relying on stale baselines saved during a prior on-session.
 */
export const initBrowserZoom = () => {
	if (typeof window === 'undefined') {
		return
	}
	try {
		if (!shouldApplyBrowserZoomHandling(window)) {
			return
		}

		const onloadDetectionEnabled = isMobileOnloadDetectionEnabled()
		if (onloadDetectionEnabled) {
			ensureAndroidBaseline(window)
		}

		const zoomFactor = detectCurrentZoomFactor(window, onloadDetectionEnabled)
		if (zoomFactor > 1) {
			freezeFonts(window, undefined, zoomFactor)
		}
	} catch (error) {
		console.error('[Browser Zoom] Failed to initialize:', error)
	}
}

initBrowserZoom()
